tton class="create-attendance-button">Salvar agenda</button></form><form class="form-card" method="post"><input type="hidden" name="csrf" value="<?=h($_SESSION['agenda_medica_csrf'])?>"><input type="hidden" name="medico" value="<?=$m?>"><input type="hidden" name="acao" value="bloquear"><h3>Bloquear período</h3><div class="form-grid"><div class="form-field"><label>Data inicial</label><input type="date" name="inicio" required></div><div class="form-field"><label>Data final</label><input type="date" name="fim" required></div><div class="form-field"><label>Motivo</label><input name="motivo" maxlength="255" required></div></div><button class="create-attendance-button">Bloquear</button></form><section class="form-card"><h3>Bloqueios cadastrados</h3><?php foreach($bs as $b):?><form method="post" style="margin:12px 0"><input type="hidden" name="csrf" value="<?=h($_SESSION['agenda_medica_csrf'])?>"><input type="hidden" name="medico" value="<?=$m?>"><input type="hidden" name="id" value="<?=$b['id']?>"><?=h($b['data_inicio'].' a '.$b['data_fim'].' — '.$b['motivo'])?> <button name="acao" value="remover">Remover bloqueio</button></form><?php endforeach;?></section><?php endif;?></section></main></div><?php require __DIR__.'/../../includes/footer.php';?>
